```go
package main

import (
	"context"
	"os"
	"strconv"

	texporter "github.com/GoogleCloudPlatform/opentelemetry-operations-go/exporter/trace"
	gcppropagator "github.com/GoogleCloudPlatform/opentelemetry-operations-go/propagator"
	"go.opentelemetry.io/contrib/detectors/gcp"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/propagation"
	"go.opentelemetry.io/otel/sdk/resource"
	sdktrace "go.opentelemetry.io/otel/sdk/trace"
	semconv "go.opentelemetry.io/otel/semconv/v1.26.0"
)

// tracer is the package-level tracer used by the service handlers.
var tracer = otel.Tracer("marvel.sm.helloworld.v1")

// setupTracing configures the global TracerProvider to export to Google Cloud
// Trace. It returns a shutdown func that flushes any pending spans.
//
// Outside Cloud Run (local dev) tracing is a no-op so we don't need creds.
func setupTracing(ctx context.Context) (func(context.Context) error, error) {
	noop := func(context.Context) error { return nil }
	if os.Getenv("K_SERVICE") == "" {
		return noop, nil
	}

	exporter, err := texporter.New(
		texporter.WithProjectID(os.Getenv("ALIS_OS_PROJECT")),
	)
	if err != nil {
		return noop, err
	}

	res, err := resource.New(ctx,
		resource.WithDetectors(gcp.NewDetector()),
		resource.WithTelemetrySDK(),
		resource.WithAttributes(
			semconv.ServiceName(os.Getenv("K_SERVICE")),
			semconv.ServiceVersion(os.Getenv("K_REVISION")),
		),
	)
	if err != nil {
		return noop, err
	}

	tp := sdktrace.NewTracerProvider(
		sdktrace.WithBatcher(exporter),
		sdktrace.WithResource(res),
		sdktrace.WithSampler(sdktrace.ParentBased(
			sdktrace.TraceIDRatioBased(sampleRatio()),
		)),
	)
	otel.SetTracerProvider(tp)

	// TraceContext handles the W3C `traceparent` header; the Cloud Trace
	// one-way propagator reads Google's `X-Cloud-Trace-Context` on the way in
	// without writing it back out.
	otel.SetTextMapPropagator(propagation.NewCompositeTextMapPropagator(
		propagation.TraceContext{},
		propagation.Baggage{},
		gcppropagator.CloudTraceOneWayPropagator{},
	))

	tracer = tp.Tracer("marvel.sm.helloworld.v1")
	return tp.Shutdown, nil
}

// sampleRatio reads OTEL_TRACE_SAMPLE_RATIO, defaulting to 10% of root traces.
func sampleRatio() float64 {
	v := os.Getenv("OTEL_TRACE_SAMPLE_RATIO")
	if v == "" {
		return 0.1
	}
	ratio, err := strconv.ParseFloat(v, 64)
	if err != nil || ratio < 0 || ratio > 1 {
		return 0.1
	}
	return ratio
}
```

## 2. `server.go` — instrument the gRPC server and flush on shutdown

Add imports `os/signal`, `syscall`, `time`, and `go.opentelemetry.io/contrib/instrumentation/google.golang.org/grpc/otelgrpc`, then replace `main`:

```go
func main() {
	ctx := context.Background()

	shutdownTracing, err := setupTracing(ctx)
	if err != nil {
		// Tracing is best-effort: log and keep serving.
		alog.Warnf(ctx, "setup tracing: %v", err)
	}

	// otelgrpc's stats handler starts a server span per RPC and extracts any
	// incoming trace context, so this must be registered on the server itself.
	grpcServer := grpc.NewServer(
		grpc.StatsHandler(otelgrpc.NewServerHandler()),
		grpc.UnaryInterceptor(unaryInterceptor),
	)
	pb.RegisterHelloWorldServiceServer(grpcServer, HelloWorldServer)

	port := ":8080"
	alog.Notice(ctx, "starting server on "+port)
	listener, err := net.Listen("tcp", port)
	if err != nil {
		alog.Fatalf(ctx, "net.Listen: %v", err.Error())
	}

	// Cloud Run sends SIGTERM before tearing the instance down; drain in-flight
	// RPCs and flush buffered spans before exiting.
	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGTERM, syscall.SIGINT)
	go func() {
		<-stop
		grpcServer.GracefulStop()
	}()

	if err = grpcServer.Serve(listener); err != nil {
		alog.Fatal(ctx, err.Error())
	}

	flushCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	if err := shutdownTracing(flushCtx); err != nil {
		alog.Warnf(ctx, "flush traces: %v", err)
	}
}
```

Also record errors on the span in your existing interceptor, so failed RPCs show up red in Cloud Trace:

```go
func unaryInterceptor(ctx context.Context, req interface{}, info *grpc.UnaryServerInfo, handler grpc.UnaryHandler) (interface{}, error) {
	h, err := handler(ctx, req)
	if err != nil {
		span := trace.SpanFromContext(ctx)
		span.RecordError(err)
		span.SetStatus(codes.Error, err.Error())

		alog.Debugf(ctx, "%s", req)
		alog.Warn(ctx, err.Error())
	}
	return h, err
}
```
