		{"trailing garbage", "2023-03-14xyz"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parseDate(tt.in)
			if err == nil {
				t.Fatalf("parseDate(%q) = %v, want error", tt.in, got)
			}
			if !got.IsZero() {
				t.Errorf("parseDate(%q) returned %v on error, want zero time", tt.in, got)
			}
			if !strings.Contains(err.Error(), "parseDate") {
				t.Errorf("parseDate(%q) error %q does not name the function", tt.in, err)
			}
			if !strings.Contains(err.Error(), tt.in) {
				t.Errorf("parseDate(%q) error %q does not include the input", tt.in, err)
			}
		})
	}
}

// The error must stay unwrappable so callers can inspect the parse failure.
func TestParseDateErrorWrapsParseError(t *testing.T) {
	_, err := parseDate("nope")
	if err == nil {
		t.Fatal(`parseDate("nope") = nil error, want error`)
	}
	var parseErr *time.ParseError
	if !errors.As(err, &parseErr) {
		t.Fatalf("parseDate error %v (%T) does not wrap *time.ParseError", err, err)
	}
	if parseErr.Value != "nope" {
		t.Errorf("wrapped ParseError.Value = %q, want %q", parseErr.Value, "nope")
	}
}

// parseDate normalizes to UTC, so the process time zone must not affect results.
func TestParseDateIgnoresLocalTimeZone(t *testing.T) {
	orig := time.Local
	t.Cleanup(func() { time.Local = orig })

	for _, name := range []string{"UTC", "America/Los_Angeles", "Asia/Tokyo", "Pacific/Kiritimati"} {
		loc, err := time.LoadLocation(name)
		if err != nil {
			t.Skipf("time zone database unavailable: %v", err)
		}
		time.Local = loc

		got, err := parseDate("2023-03-14")
		if err != nil {
			t.Fatalf("parseDate with Local=%s returned error: %v", name, err)
		}
		want := time.Date(2023, time.March, 14, 0, 0, 0, 0, time.UTC)
		if !got.Equal(want) || got.Location() != time.UTC {
			t.Errorf("parseDate with Local=%s = %v (%v), want %v (UTC)", name, got, got.Location(), want)
		}
	}
}

func TestParseDateRoundTrip(t *testing.T) {
	const layout = "2006-01-02"
	for d := time.Date(2023, time.January, 1, 0, 0, 0, 0, time.UTC); d.Year() == 2023; d = d.AddDate(0, 0, 1) {
		s := d.Format(layout)
		got, err := parseDate(s)
		if err != nil {
			t.Fatalf("parseDate(%q) returned error: %v", s, err)
		}
		if !got.Equal(d) {
			t.Fatalf("parseDate(%q) = %v, want %v", s, got, d)
		}
		if out := got.Format(layout); out != s {
			t.Fatalf("parseDate(%q).Format(layout) = %q, want %q", s, out, s)
		}
	}
}
```

Two notes on coverage decisions:

- `got.Equal(want)` alone would pass for a correct instant in the wrong location, so the location and clock-field checks are separate assertions — that's what actually pins down "midnight UTC".
- The error cases assert behavior (non-nil error, zero time, input echoed, `*time.ParseError` recoverable via `errors.As`) rather than exact message text, so they survive Go changing its parse-error wording.

Caveat I couldn't rule out by running: the expected failures for `"2023-3-14"`, `"2023-02-30"`, and `"2023-02-29"` rest on `time.Parse` requiring zero-padded fields for the `01`/`02` layout elements and validating day-of-month. I'm confident that's current behavior, but `go test ./dates` is the real check.

Separately: `t.UTC()` in `parseDate` is a no-op — `time.Parse` with a zone-less layout already returns a UTC time. Harmless, and `TestParseDateIgnoresLocalTimeZone` passes either way.
